#!/usr/bin/env node
// A deliberately ordinary CLI: one flag that takes a value, one boolean flag, and a documented exit code of 2 for
// anything it does not understand. The fixture asserts on argv parsing and on the exit code, not on output prettiness.
import fs from "node:fs";

const argv = process.argv.slice(2);
let input = null;
let upper = false;

for (let i = 0; i < argv.length; i += 1) {
  const arg = argv[i];
  if (arg === "--input") {
    input = typeof argv[i + 1] === "string" ? argv[i + 1] : null;
    i += 1;
  } else if (arg === "--upper") {
    upper = true;
  } else {
    console.error("unknown flag: " + arg);
    process.exit(2);
  }
}

if (input === null) {
  console.error("usage: cli.mjs --input <file> [--upper]");
  process.exit(2);
}

const text = fs.readFileSync(input, "utf8").trim();
console.log(upper ? text.toUpperCase() : text);
